/** @param {unknown} v @returns {import('./contracts').Summary} */export function summary(v){const r=record(v),counts=record(r.delegationCounts);return {id:identifier(r.id),authority:choice(r.authority,/** @type {const} */(['NATIVE','EXTERNAL'])),status:choice(r.status,SESSION),version:integer(r.version),rootTaskId:maybeId(r.rootTaskId),createdAt:date(r.createdAt),updatedAt:date(r.updatedAt),finishedAt:maybeDate(r.finishedAt),participantCount:integer(r.participantCount),delegationCounts:{total:integer(counts.total),active:integer(counts.active),completed:integer(counts.completed),failed:integer(counts.failed),cancelled:integer(counts.cancelled)}};}
/** @param {unknown} v @returns {import('./contracts').ExternalObservation} */function external(v){const r=record(v),e=record(r.execution),id=identifier(r.mappingId);if(r.type!=='EXTERNAL_OBSERVATION'||r.activityId!=='external:'+id||e.authority!=='EXTERNAL'||identifier(e.mappingId)!==id||r.progress!==null||r.connectionHealth!=='UNKNOWN'||r.resultAvailability!=='NOT_PROJECTED'||!Array.isArray(r.operations)||r.operations.length)throw new RuntimeApiError('SCHEMA');return {activityId:'external:'+id,type:'EXTERNAL_OBSERVATION',mappingId:id,collaborationId:maybeId(r.collaborationId),delegationId:maybeId(r.delegationId),agentId:maybeId(r.agentId),version:integer(r.version),execution:{authority:'EXTERNAL',mappingId:id,sourceId:identifier(e.sourceId),connectionId:identifier(e.connectionId),namespace:text(e.namespace,64),generation:integer(e.generation),adapterType:text(e.adapterType,64),externalAgentId:text(e.externalAgentId),externalExecutionId:text(e.externalExecutionId),status:choice(e.status,['UNKNOWN','QUEUED','RUNNING','COMPLETED','FAILED','CANCELLED']),sourceStatus:maybeText(e.sourceStatus)},sourceOccurredAt:maybeDate(r.sourceOccurredAt),observedAt:maybeDate(r.observedAt),updatedAt:date(r.updatedAt),freshness:choice(r.freshness,/** @type {const} */(['RECENT_OBSERVATION','STALE','RETIRED','UNKNOWN'])),connectionHealth:'UNKNOWN',progress:null,resultAvailability:'NOT_PROJECTED',operations:[]};}
