/** @param {unknown} value @param {string} agentId @returns {import('./contracts').AgentView} */export function agentView(value,agentId){const {r,observedAt}=header(value);if(identifier(r.agentId)!==agentId||normalizeActivity(r.baseActivity).agentId!==agentId||r.progress!==null)throw new RuntimeApiError('SCHEMA');const collaborations=page(r.collaborations,v=>{const m=record(v);return {id:identifier(m.id),authority:choice(m.authority,/** @type {const} */(['NATIVE','EXTERNAL'])),status:choice(m.status,SESSION),version:integer(m.version),role:choice(m.role,['COORDINATOR','DELEGATE']),leftAt:maybeDate(m.leftAt)};},v=>v.id);const ext=page(r.external,external,v=>v.mappingId);if(ext.items.some(v=>v.agentId!==agentId))throw new RuntimeApiError('SCHEMA');return {schemaVersion:2,observedAt,agentId,collaborations,external:ext};}
