/** @param {unknown} value @returns {import('./contracts').Timeline} */export function timeline(value){const {r,observedAt}=header(value);if(r.synchronization!==false)throw new RuntimeApiError('SCHEMA');const p=page(r,v=>{const e=record(v),id=text(e.id,64);if(!/^(event|audit|inbox):[0-9a-f-]{36}$/.test(id))throw new RuntimeApiError('SCHEMA');return {id,type:text(e.type,128),at:date(e.at),sourceOccurredAt:maybeDate(e.sourceOccurredAt),correlationId:identifier(e.correlationId),delegationId:maybeId(e.delegationId),provenance:choice(e.provenance,/** @type {const} */(['PERSISTED_EVENT','CONTROL_AUDIT','EXTERNAL_INBOX'])),processingStatus:maybeText(e.processingStatus),execution:null};},v=>v.id,true);if(p.items.some((v,i)=>i>0&&v.at>p.items[i-1].at))throw new RuntimeApiError('SCHEMA');return {schemaVersion:2,observedAt,...p,synchronization:false};}
